import { createHash, randomUUID } from "node:crypto";
import type pg from "pg";
import { assertMediaConfiguration } from "@growdesk/adapters";
import { requireWebBaby, WebAccessError, withWebTransaction, type Queryable } from "@growdesk/database";
import type { WebJob, WebJobCreate, WebJobListQuery, WebVoiceLogInput } from "@growdesk/contracts";

interface JobRow {
  id:string; user_id:string; family_id:string; baby_id:string; kind:WebJobCreate["type"];
  client_request_id:string; request_hash:string; input:WebJobCreate & {archived?:boolean;imageUrl?:string|null}; claimed:boolean;
  created_at:Date; status:string; attempt:number; max_attempts:number;
  result_ref:unknown; error_details:{message?:string}|null; last_heartbeat_at:Date|null; updated_at:Date;
}
const selectJob = `SELECT j.*, t.status, t.attempt, t.max_attempts, t.result_ref, t.error_details, t.last_heartbeat_at, t.updated_at
  FROM web_background_jobs j JOIN task_executions t ON t.id=j.id`;
const visible = `EXISTS (SELECT 1 FROM baby_members bm JOIN babies b ON b.id=bm.baby_id AND b.family_id=bm.family_id
  JOIN family_members fm ON fm.family_id=b.family_id AND fm.user_id=bm.user_id JOIN families f ON f.id=b.family_id
  WHERE bm.user_id=j.user_id AND bm.baby_id=j.baby_id AND bm.family_id=j.family_id
    AND bm.status='active' AND bm.deleted_at IS NULL AND fm.status='active' AND fm.deleted_at IS NULL
    AND b.deleted_at IS NULL AND f.deleted_at IS NULL)`;
function jobDto(row: JobRow): WebJob {
  return { id:row.id,userId:row.user_id,familyId:row.family_id,babyId:row.baby_id,type:row.kind,
    status:row.status==='queued'?'pending':row.status as WebJob["status"],
    resultJson:row.result_ref==null?null:JSON.stringify(row.result_ref),errorMessage:row.error_details?.message??null,
    imageUrl:row.input.attachmentId?`/api/attachments/${row.input.attachmentId}`:row.input.imageUrl??null,claimed:row.claimed,
    attempt:row.attempt,maxAttempts:row.max_attempts,createdAt:row.created_at.toISOString(),
    startedAt:row.last_heartbeat_at?.toISOString()??null,
    finishedAt:['succeeded','failed','cancelled'].includes(row.status)?row.updated_at.toISOString():null };
}
async function enqueue(db: Queryable, id: string, kind: string, phase: string): Promise<void> {
  await db.query(`INSERT INTO task_outbox(id,type,aggregate_id,payload_version,payload,phase_key,dispatch_state,next_dispatch_at,created_at)
    VALUES($1,$2,$3,1,'{}',$4,'active',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)`,[randomUUID(),kind,id,phase]);
}
export class WebBackgroundService {
  constructor(private readonly pool: pg.Pool, private readonly env: NodeJS.ProcessEnv = process.env) {}
  private async owned(db: Queryable,userId:string,id:string,lock=false): Promise<JobRow> {
    const result=await db.query<JobRow>(`${selectJob} WHERE j.id=$1 AND j.user_id=$2 AND ${visible}${lock?' FOR UPDATE OF j,t':''}`,[id,userId]);
    const row=result.rows[0];
    if(!row) throw new WebAccessError(404,'JOB_NOT_FOUND','Task not found or no longer authorized');
    await requireWebBaby(db,userId,row.baby_id,lock);
    return row;
  }
  async create(userId:string,input:WebJobCreate):Promise<WebJob> {
    const normalized:WebJobCreate={type:input.type,babyId:input.babyId,clientRequestId:input.clientRequestId};
    if(input.type==='daily_summary_synthesis') {
      if(!input.targetDate || input.attachmentId || !Number.isFinite(Date.parse(`${input.targetDate}T00:00:00Z`)) || new Date(`${input.targetDate}T00:00:00Z`).toISOString().slice(0,10)!==input.targetDate) throw new WebAccessError(400,'INVALID_JOB_INPUT','A valid target date, and no attachment, are required');
      normalized.targetDate=input.targetDate;
    } else {
      if(!input.attachmentId || input.targetDate) throw new WebAccessError(400,'INVALID_JOB_INPUT','A completed private attachment is required');
      normalized.attachmentId=input.attachmentId;
    }
    const hash=createHash('sha256').update(JSON.stringify(normalized)).digest('hex');
    return withWebTransaction(this.pool,async db=>{
      const baby=await requireWebBaby(db,userId,input.babyId,true,input.type==='daily_summary_synthesis');
      await db.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))',[`${userId}:${input.type}:${input.clientRequestId}`]);
      const prior=await db.query<{id:string;request_hash:string}>(`SELECT id,request_hash FROM web_background_jobs WHERE user_id=$1 AND kind=$2 AND client_request_id=$3`,[userId,input.type,input.clientRequestId]);
      if(prior.rows[0]) {
        if(prior.rows[0].request_hash!==hash) throw new WebAccessError(409,'IDEMPOTENCY_KEY_REUSED','Request key already has different content');
        return jobDto(await this.owned(db,userId,prior.rows[0].id));
      }
      assertMediaConfiguration(input.type,this.env);
      if(normalized.attachmentId) {
        const attachment=await db.query<{mime_type:string;byte_size:number}>(`SELECT mime_type,byte_size FROM attachments WHERE id=$1 AND family_id=$2 AND baby_id=$3 AND uploader_id=$4 AND status='ready' AND deleted_at IS NULL FOR SHARE`,[normalized.attachmentId,baby.family_id,input.babyId,userId]);
        const row=attachment.rows[0];
        if(!row) throw new WebAccessError(404,'ATTACHMENT_NOT_FOUND','Attachment not found or not ready');
        const types=input.type==='voice_transcription'?['audio/mpeg','audio/mp3','audio/mp4','audio/wav','audio/x-wav','audio/webm','audio/ogg','video/webm']:['image/jpeg','image/png','image/webp'];
        if(!types.includes(row.mime_type)||row.byte_size<1||row.byte_size>25_000_000) throw new WebAccessError(400,'INVALID_MEDIA','Unsupported media type or size');
      }
      const id=randomUUID();
      // One attempt means a lost worker does not silently make a second paid request.
      await db.query(`INSERT INTO task_executions(id,kind,owner_scope,status,attempt,max_attempts,fence_token,next_event_seq,created_at,updated_at)
        VALUES($1,$2,$3,'queued',0,1,0,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)`,[id,input.type,`user:${userId}`]);
      await db.query(`INSERT INTO web_background_jobs(id,user_id,family_id,baby_id,kind,client_request_id,request_hash,input)
        VALUES($1,$2,$3,$4,$5,$6,$7,$8::jsonb)`,[id,userId,baby.family_id,input.babyId,input.type,input.clientRequestId,hash,JSON.stringify(normalized)]);
      await enqueue(db,id,input.type,'initial');
      return jobDto(await this.owned(db,userId,id));
    });
  }
  async get(userId:string,id:string):Promise<WebJob> { return jobDto(await this.owned(this.pool,userId,id)); }
  async list(userId:string,query:WebJobListQuery):Promise<{total:number;pendingClaim:number;jobs:WebJob[]}> {
    const where=`j.user_id=$1 AND ($2::text IS NULL OR j.kind=$2) AND ($3::text IS NULL OR j.baby_id=$3) AND ${visible}`;
    const args=[userId,query.type??null,query.babyId??null];
    const counts=await this.pool.query<{total:string;pending:string}>(`SELECT count(*) AS total,count(*) FILTER(WHERE t.status='succeeded' AND NOT j.claimed) AS pending FROM web_background_jobs j JOIN task_executions t ON t.id=j.id WHERE ${where}`,args);
    const rows=await this.pool.query<JobRow>(`${selectJob} WHERE ${where} ORDER BY j.created_at DESC,j.id DESC LIMIT $4 OFFSET $5`,[...args,query.limit??30,query.offset??0]);
    return {total:Number(counts.rows[0]!.total),pendingClaim:Number(counts.rows[0]!.pending),jobs:rows.rows.map(jobDto)};
  }
  async act(userId:string,id:string,action:'claim'|'cancel'|'retry',commandId?:string):Promise<WebJob> {
    return withWebTransaction(this.pool,async db=>{
      const row=await this.owned(db,userId,id,true);
      if(action==='claim') {
        if(row.status!=='succeeded') throw new WebAccessError(409,'JOB_NOT_SUCCEEDED','Only a completed result can be claimed');
        await db.query('UPDATE web_background_jobs SET claimed=TRUE WHERE id=$1 AND user_id=$2',[id,userId]);
      } else if(action==='cancel') {
        if(!['succeeded','failed','cancelled'].includes(row.status)) {
          await db.query(`UPDATE task_executions SET status='cancelled',cancel_requested_at=CURRENT_TIMESTAMP,fence_token=fence_token+1,lease_owner=NULL,lease_expires_at=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=$1`,[id]);
          await db.query(`UPDATE task_outbox SET dispatch_state='closed',terminal_at=CURRENT_TIMESTAMP WHERE aggregate_id=$1`,[id]);
        }
      } else {
        if(row.input.archived) throw new WebAccessError(409,'LEGACY_JOB_REQUIRES_RESUBMISSION','Archived jobs require a new private attachment and explicit new submission');
        if(!commandId) throw new WebAccessError(400,'RETRY_COMMAND_REQUIRED','An explicit retry command is required');
        const replay=await db.query('SELECT 1 FROM web_job_retries WHERE job_id=$1 AND command_id=$2',[id,commandId]);
        if(!replay.rowCount) {
          if(!['failed','cancelled'].includes(row.status)) throw new WebAccessError(409,'JOB_NOT_RETRYABLE','Only failed/cancelled work can be explicitly retried');
          assertMediaConfiguration(row.kind,this.env);
          await db.query('INSERT INTO web_job_retries(job_id,command_id) VALUES($1,$2)',[id,commandId]);
          await db.query(`UPDATE task_executions SET status='queued',max_attempts=attempt+1,fence_token=fence_token+1,
            cancel_requested_at=NULL,lease_owner=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,result_ref=NULL,error_details=NULL,progress=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=$1`,[id]);
          await db.query('UPDATE web_background_jobs SET claimed=FALSE WHERE id=$1',[id]);
          await enqueue(db,id,row.kind,`retry:${commandId}`);
        }
      }
      return jobDto(await this.owned(db,userId,id));
    });
  }
  async createVoiceLog(userId:string,input:WebVoiceLogInput) {
    return withWebTransaction(this.pool,async db=>{
      const baby=await requireWebBaby(db,userId,input.babyId,true);
      await db.query(`INSERT INTO web_voice_logs(id,user_id,family_id,baby_id,prompt,reply,is_async,is_fast_path,acknowledged)
        VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(id) DO NOTHING`,[input.id,userId,baby.family_id,input.babyId,input.prompt,input.reply,input.isAsync,input.isFastPath,input.acknowledged??false]);
      const result=await db.query<VoiceRow>('SELECT * FROM web_voice_logs WHERE id=$1 AND user_id=$2',[input.id,userId]);
      const row=result.rows[0];
      if(!row||row.baby_id!==input.babyId||row.prompt!==input.prompt||row.reply!==input.reply||row.is_async!==input.isAsync||row.is_fast_path!==input.isFastPath) throw new WebAccessError(409,'VOICE_LOG_ID_REUSED','Voice log identifier already has different content');
      return voiceDto(row,baby.nickname);
    });
  }
  async listVoiceLogs(userId:string,options:{limit?:number;unreadAsyncOnly?:boolean}) {
    const where=`j.user_id=$1 AND ${visible}`;
    const rows=await this.pool.query<VoiceRow & {nickname:string}>(`SELECT j.*,b.nickname FROM web_voice_logs j JOIN babies b ON b.id=j.baby_id WHERE ${where}
      AND ($2::boolean=FALSE OR (j.is_async AND NOT j.acknowledged)) ORDER BY j.created_at DESC,j.id DESC LIMIT $3`,[userId,options.unreadAsyncOnly??false,options.limit??20]);
    const unread=await this.pool.query<VoiceRow & {nickname:string}>(`SELECT j.*,b.nickname FROM web_voice_logs j JOIN babies b ON b.id=j.baby_id WHERE ${where} AND j.is_async AND NOT j.acknowledged ORDER BY j.created_at DESC,j.id DESC LIMIT 1`,[userId]);
    return {logs:rows.rows.map(r=>voiceDto(r,r.nickname)),unreadLog:unread.rows[0]?voiceDto(unread.rows[0],unread.rows[0].nickname):null};
  }
  async getVoiceLog(userId:string,id:string) {
    const rows=await this.pool.query<VoiceRow>("SELECT * FROM web_voice_logs WHERE id=$1 AND user_id=$2",[id,userId]);
    if(!rows.rows[0]) throw new WebAccessError(404,"VOICE_LOG_NOT_FOUND","Voice log not found");
    const baby=await requireWebBaby(this.pool,userId,rows.rows[0].baby_id);
    return voiceDto(rows.rows[0],baby.nickname);
  }
  async acknowledgeVoiceLog(userId:string,id:string,acknowledged=true) {
    return withWebTransaction(this.pool,async db=>{
      const rows=await db.query<{baby_id:string}>('SELECT baby_id FROM web_voice_logs WHERE id=$1 AND user_id=$2 FOR UPDATE',[id,userId]);
      if(!rows.rows[0]) throw new WebAccessError(404,'VOICE_LOG_NOT_FOUND','Voice log not found');
      await requireWebBaby(db,userId,rows.rows[0].baby_id,true);
      await db.query('UPDATE web_voice_logs SET acknowledged=$3 WHERE id=$1 AND user_id=$2',[id,userId,acknowledged]);
      return {acknowledged};
    });
  }
  async deleteNotification(userId:string,id:string) {
    const result=await this.pool.query('DELETE FROM notifications WHERE id=$1 AND user_id=$2 RETURNING id',[id,userId]);
    if(!result.rowCount) throw new WebAccessError(404,'NOTIFICATION_NOT_FOUND','Notification not found');
    return {success:true as const};
  }
}
interface VoiceRow {id:string;user_id:string;baby_id:string;prompt:string;reply:string;is_async:boolean;is_fast_path:boolean;acknowledged:boolean;created_at:Date}
function voiceDto(row:VoiceRow,nickname:string) {
  return {id:row.id,userId:row.user_id,babyId:row.baby_id,prompt:row.prompt,reply:row.reply,isAsync:row.is_async,isFastPath:row.is_fast_path,acknowledged:row.acknowledged,createdAt:row.created_at.toISOString(),baby:{id:row.baby_id,nickname}};
}
